package com.rustyvault.legacy;

import com.rustyvault.CustomerDirectory;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

public class LegacyCustomerDirectory implements CustomerDirectory {

    private final Connection conn;

    public LegacyCustomerDirectory(Connection conn) {
        this.conn = conn;
    }

    private void validateNumeric(String value) {
        if (value == null || value.isEmpty() || value.length() > 18 || !value.matches("\\d+")) {
            throw new IllegalArgumentException("Invalid numeric format");
        }
    }

    private String formatRow(ResultSet rs) throws SQLException {
        return rs.getLong("id") + "|" + rs.getString("name") + "|" + rs.getString("city") + "|" + rs.getLong("balance_cents");
    }

    @Override
    public long addCustomer(String name, String city, long balanceCents) {
        if (name == null || name.isBlank() || city == null || city.isBlank() || balanceCents < 0) {
            throw new IllegalArgumentException("Invalid customer data");
        }
        try (PreparedStatement ps = conn.prepareStatement(
                "INSERT INTO customer (name, city, balance_cents) VALUES (?, ?, ?)",
                Statement.RETURN_GENERATED_KEYS)) {
            ps.setString(1, name);
            ps.setString(2, city);
            ps.setLong(3, balanceCents);
            ps.executeUpdate();
            try (ResultSet keys = ps.getGeneratedKeys()) {
                if (keys.next()) {
                    return keys.getLong(1);
                }
                throw new SQLException("No ID generated");
            }
        } catch (SQLException e) {
            throw new IllegalStateException(e);
        }
    }

    @Override
    public List<String> findByName(String name) {
        if (name == null) throw new IllegalArgumentException("Name cannot be null");
        List<String> results = new ArrayList<>();
        try (PreparedStatement ps = conn.prepareStatement(
                "SELECT id, name, city, balance_cents FROM customer WHERE name = ? ORDER BY id")) {
            ps.setString(1, name);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) results.add(formatRow(rs));
            }
        } catch (SQLException e) {
            throw new IllegalStateException(e);
        }
        return results;
    }

    @Override
    public List<String> searchByNamePrefix(String prefix) {
        if (prefix == null) throw new IllegalArgumentException("Prefix cannot be null");
        String escaped = prefix.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_");
        List<String> results = new ArrayList<>();
        try (PreparedStatement ps = conn.prepareStatement(
                "SELECT id, name, city, balance_cents FROM customer WHERE UPPER(name) LIKE UPPER(?) ESCAPE '\\' ORDER BY id")) {
            ps.setString(1, escaped + "%");
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) results.add(formatRow(rs));
            }
        } catch (SQLException e) {
            throw new IllegalStateException(e);
        }
        return results;
    }

    @Override
    public List<String> list(String sortBy, boolean descending) {
        String column;
        if ("id".equals(sortBy)) column = "id";
        else if ("name".equals(sortBy)) column = "name";
        else if ("city".equals(sortBy)) column = "city";
        else if ("balance".equals(sortBy)) column = "balance_cents";
        else throw new IllegalArgumentException("Invalid sort key");

        String sql = "SELECT id, name, city, balance_cents FROM customer ORDER BY " + column + (descending ? " DESC" : " ASC") + ", id ASC";
        List<String> results = new ArrayList<>();
        try (Statement st = conn.createStatement(); ResultSet rs = st.executeQuery(sql)) {
            while (rs.next()) results.add(formatRow(rs));
        } catch (SQLException e) {
            throw new IllegalStateException(e);
        }
        return results;
    }

    @Override
    public String getById(String id) {
        validateNumeric(id);
        try (PreparedStatement ps = conn.prepareStatement(
                "SELECT id, name, city, balance_cents FROM customer WHERE id = ?")) {
            ps.setLong(1, Long.parseLong(id));
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) return formatRow(rs);
            }
        } catch (SQLException e) {
            throw new IllegalStateException(e);
        }
        return null;
    }

    @Override
    public List<String> findByIds(List<String> ids) {
        if (ids == null) throw new IllegalArgumentException("List cannot be null");
        if (ids.isEmpty()) return List.of();
        Set<Long> uniqueIds = new HashSet<>();
        for (String id : ids) {
            validateNumeric(id);
            uniqueIds.add(Long.parseLong(id));
        }
        String placeholders = uniqueIds.stream().map(v -> "?").collect(Collectors.joining(","));
        List<String> results = new ArrayList<>();
        try (PreparedStatement ps = conn.prepareStatement(
                "SELECT id, name, city, balance_cents FROM customer WHERE id IN (" + placeholders + ") ORDER BY id")) {
            int i = 1;
            for (Long id : uniqueIds.stream().sorted().collect(Collectors.toList())) {
                ps.setLong(i++, id);
            }
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) results.add(formatRow(rs));
            }
        } catch (SQLException e) {
            throw new IllegalStateException(e);
        }
        return results;
    }

    @Override
    public List<String> richerThan(String minBalanceCents) {
        validateNumeric(minBalanceCents);
        List<String> results = new ArrayList<>();
        try (PreparedStatement ps = conn.prepareStatement(
                "SELECT id, name, city, balance_cents FROM customer WHERE balance_cents > ? ORDER BY id")) {
            ps.setLong(1, Long.parseLong(minBalanceCents));
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) results.add(formatRow(rs));
            }
        } catch (SQLException e) {
            throw new IllegalStateException(e);
        }
        return results;
    }

    @Override
    public List<String> sameCityAs(String id) {
        validateNumeric(id);
        long numericId = Long.parseLong(id);
        try (PreparedStatement psCity = conn.prepareStatement("SELECT city FROM customer WHERE id = ?")) {
            psCity.setLong(1, numericId);
            try (ResultSet rsCity = psCity.executeQuery()) {
                if (!rsCity.next()) throw new IllegalArgumentException("Customer not found");
                String city = rsCity.getString(1);
                List<String> results = new ArrayList<>();
                try (PreparedStatement ps = conn.prepareStatement(
                        "SELECT id, name, city, balance_cents FROM customer WHERE city = ? AND id <> ? ORDER BY id")) {
                    ps.setString(1, city);
                    ps.setLong(2, numericId);
                    try (ResultSet rs = ps.executeQuery()) {
                        while (rs.next()) results.add(formatRow(rs));
                    }
                }
                return results;
            }
        } catch (SQLException e) {
            throw new IllegalStateException(e);
        }
    }

    @Override
    public int deleteByCity(String city) {
        if (city == null) throw new IllegalArgumentException("City cannot be null");
        try (PreparedStatement ps = conn.prepareStatement("DELETE FROM customer WHERE city = ?")) {
            ps.setString(1, city);
            return ps.executeUpdate();
        } catch (SQLException e) {
            throw new IllegalStateException(e);
        }
    }

    @Override
    public int count() {
        try (Statement st = conn.createStatement(); ResultSet rs = st.executeQuery("SELECT COUNT(*) FROM customer")) {
            rs.next();
            return rs.getInt(1);
        } catch (SQLException e) {
            throw new IllegalStateException(e);
        }
    }
}
